93			t.Fatalf("item 13 should choose c, got %+v", r)
94		}
95		// Item 14: excluding every healthy instance is no_healthy, and the reason
96		// says the exclusion removed them all.
97		if r := got.Results[13]; r.OK || r.Error != "no_healthy" ||
98			!strings.Contains(r.Reason, "excludeInstanceIds") || r.Revision != 1 {
