148		// filtered rotation (cursor on a, candidates {b}) and rebinds k -> b.
149		if r := got.Results[4]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" {
150			t.Fatalf("item 5 should fall back to b, got %+v", r)
151		}
152		// Item 6 reuses the new binding b without a list.
153		if r := got.Results[5]; !r.OK || r.InstanceID != "b" {
154			t.Fatalf("item 6 should reuse b, got %+v", r)
155		}
156		// Item 7: the plain rotation continues just after the last real rotation
157		// (b) and wraps to a — the exclusion removed nothing durably.
158		if r := got.Results[6]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" {
159			t.Fatalf("item 7 should choose a, got %+v", r)
160		}
161	}
