624	func TestSelectAddressReplacementKeepsRotation(t *testing.T) {
625		// One instance keeps its id but gets a new address: the registration bumps
626		// once, that instance resets to unknown/0 while untouched instances keep
627		// their observations, and the rotation continues after the last chosen id
628		// instead of restarting at the smallest id.
629		input := `{"requests":[
630			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
631			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
632			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
633			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
634			{"type":"health","service":"svc","instanceId":"d","expectedRevision":1,"sequence":14,"healthy":false,"reason":"connection refused"},
635			{"type":"select","service":"svc","expectedRevision":1},
636			{"type":"select","service":"svc","expectedRevision":1},
637			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
638			{"type":"select","service":"svc","expectedRevision":2},
639			{"type":"select","service":"svc","expectedRevision":2}
640		]}`
641		out, code := runRegisterWith(t, input)
642		if code != 0 {
643			t.Fatalf("exit code: %d, output: %s", code, out)
644		}
645		var got registerOutput
646		if err := json.Unmarshal([]byte(out), &got); err != nil {
647			t.Fatalf("output is not JSON: %v\n%s", err, out)
648		}
649		if len(got.Results) != 10 {
650			t.Fatalf("results: %+v", got.Results)
651		}
652		// Rotation before the replacement: a then b, cursor rests on b.
653		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 {
654			t.Fatalf("first select: %+v", r)
655		}
656		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 {
657			t.Fatalf("second select: %+v", r)
658		}
659		// The address-only replacement succeeds and bumps the revision exactly once.
660		if r := got.Results[7]; !r.OK || !r.Changed || r.Revision != 2 {
661			t.Fatalf("address replacement: %+v", r)
662		}
663		// The new address of a has no observation yet, so it is skipped; the
664		// rotation continues just after b and lands on c, never on a's old address.
665		if r := got.Results[8]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 13 || r.Revision != 2 {
666			t.Fatalf("select after replacement should continue after b at c: %+v", r)
667		}
668		// Past the end the rotation wraps to the smallest eligible id (b), proving
669		// it did not restart from the smallest id because of the replacement.
670		if r := got.Results[9]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 2 {
671			t.Fatalf("select should wrap to smallest eligible id: %+v", r)
672		}
673		// Final state: a is unknown at sequence 0 with no leftover reason; the
674		// untouched instances keep their health, sequence and reason.
675		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
676			t.Fatalf("services: %+v", got.Services)
677		}
678		insts := got.Services[0].Instances
679		if len(insts) != 4 {
680			t.Fatalf("instances: %+v", insts)
681		}
682		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "unknown" || insts[0].Sequence != 0 || insts[0].Reason != "" {
683			t.Fatalf("replaced instance should reset to unknown/0: %+v", insts[0])
684		}
685		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 12 {
686			t.Fatalf("b should keep its observation: %+v", insts[1])
687		}
688		if insts[2].ID != "c" || insts[2].Health != "healthy" || insts[2].Sequence != 13 {
689			t.Fatalf("c should keep its observation: %+v", insts[2])
690		}
691		if insts[3].ID != "d" || insts[3].Health != "unhealthy" || insts[3].Sequence != 14 || insts[3].Reason != "connection refused" {
692			t.Fatalf("d should keep its observation and reason: %+v", insts[3])
693		}
694	}
