1104	// TestEmptyListReplacementKeepsRotationAndDropsHealth is the regression guard
1105	// for replacing a service's instance list with an empty one and later
1106	// re-adding the very same ids and addresses: the empty list must not delete
1107	// the service or its rotation position, and the re-added instances must not
1108	// recover the health observations recorded before the clear. The batch walks
1109	// the full lifecycle:
1110	//
1111	//   - a, b, c registered at revision 1; a and b observed healthy, c observed
1112	//     unhealthy with a reason, all at sequences above 1;
1113	//   - two successful selections return a then b, leaving the cursor on b;
1114	//   - a replacement with an empty instance list succeeds, reports changed and
1115	//     bumps the revision to 2; the service survives, so a selection at
1116	//     revision 2 is no_healthy (never not_found) and names neither an old
1117	//     instance id nor an old address;
1118	//   - re-registering the original ids and addresses at revision 2 bumps the
1119	//     revision to 3; all three instances are back to unknown at sequence 0
1120	//     with no reason, so nothing is selectable yet;
1121	//   - health observations sent under the pre-clear revisions conflict even
1122	//     with larger sequences, naming the request and current revisions, and
1123	//     restore no eligibility; fresh observations at revision 3 with sequence 1
1124	//     succeed without bumping the registration revision;
1125	//   - the next successful selection continues just after b and returns c with
1126	//     its current address and sequence 1, and only the following one wraps
1127	//     back to a — the failed selections in between never moved the cursor.
1128	//
1129	// The batch contains failures, so the exit status is 1; the failed items keep
1130	// their result slots and the final list is sorted by id and reflects only the
1131	// newly accepted observations.
1132	func TestEmptyListReplacementKeepsRotationAndDropsHealth(t *testing.T) {
1133		input := `{"requests":[
1134			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1135			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
1136			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
1137			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":false,"reason":"心跳超时"},
1138			{"type":"select","service":"svc","expectedRevision":1},
1139			{"type":"select","service":"svc","expectedRevision":1},
1140			{"type":"register","service":"svc","expectedRevision":1,"instances":[]},
1141			{"type":"select","service":"svc","expectedRevision":2},
1142			{"type":"register","service":"svc","expectedRevision":2,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1143			{"type":"select","service":"svc","expectedRevision":3},
1144			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
1145			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":98,"healthy":true},
1146			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":97,"healthy":true},
1147			{"type":"select","service":"svc","expectedRevision":3},
1148			{"type":"health","service":"svc","instanceId":"a","expectedRevision":3,"sequence":1,"healthy":true},
1149			{"type":"health","service":"svc","instanceId":"b","expectedRevision":3,"sequence":1,"healthy":true},
1150			{"type":"health","service":"svc","instanceId":"c","expectedRevision":3,"sequence":1,"healthy":true},
1151			{"type":"select","service":"svc","expectedRevision":3},
1152			{"type":"select","service":"svc","expectedRevision":3}
1153		]}`
1154		out, code := runRegisterWith(t, input)
1155		if code != 1 {
1156			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
1157		}
1158		var got registerOutput
1159		if err := json.Unmarshal([]byte(out), &got); err != nil {
1160			t.Fatalf("output is not JSON: %v\n%s", err, out)
1161		}
1162		// One result per request, in input order; failed items keep their slots.
1163		if len(got.Results) != 19 {
1164			t.Fatalf("results: %+v", got.Results)
1165		}
1166		// 0: registration accepted at revision 1.
1167		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
1168			t.Fatalf("result 0: %+v", r)
1169		}
1170		// 1-3: observations accepted without bumping the registration revision.
1171		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
1172			t.Fatalf("result 1: %+v", r)
1173		}
1174		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 12 {
1175			t.Fatalf("result 2: %+v", r)
1176		}
1177		if r := got.Results[3]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 13 {
1178			t.Fatalf("result 3: %+v", r)
1179		}
1180		// 4-5: the first two selections rotate a then b; the cursor rests on b.
1181		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
1182			t.Fatalf("result 4: %+v", r)
1183		}
1184		if r := got.Results[5]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 1 {
1185			t.Fatalf("result 5: %+v", r)
1186		}
1187		// 6: clearing the instance list succeeds, reports the change and bumps the
1188		// revision to 2.
1189		if r := got.Results[6]; !r.OK || !r.Changed || r.Revision != 2 {
1190			t.Fatalf("result 6: %+v", r)
1191		}
1192		// 7: the empty list keeps the service alive at revision 2, so the answer is
1193		// no_healthy — never not_found — with a readable reason, the current
1194		// revision, and no leftover instance id or address from before the clear.
1195		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1196			r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
1197			t.Fatalf("result 7 no_healthy on empty list: %+v", r)
1198		}
1199		// 8: re-adding the original ids and addresses succeeds and bumps the
1200		// revision to 3.
1201		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 3 {
1202			t.Fatalf("result 8: %+v", r)
1203		}
1204		// 9: identical ids and addresses do not bring the old observations back:
1205		// all three instances are unknown again, so the selection is no_healthy.
1206		if r := got.Results[9]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1207			r.Revision != 3 || r.InstanceID != "" || r.Address != "" {
1208			t.Fatalf("result 9 no_healthy after re-register: %+v", r)
1209		}
1210		// 10-12: observations under the pre-clear revisions conflict even though
1211		// their sequences exceed the old accepted ones; each names the request and
1212		// current revisions and restores no eligibility.
1213		if r := got.Results[10]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1214			!hasRevisionPair(r, 1, 3) || r.Revision != 3 {
1215			t.Fatalf("result 10 stale-revision report: %+v", r)
1216		}
1217		if r := got.Results[11]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1218			!hasRevisionPair(r, 2, 3) || r.Revision != 3 {
1219			t.Fatalf("result 11 stale-revision report: %+v", r)
1220		}
1221		if r := got.Results[12]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1222			!hasRevisionPair(r, 1, 3) || r.Revision != 3 {
1223			t.Fatalf("result 12 stale-revision report: %+v", r)
1224		}
1225		// 13: the conflicting reports healed nothing — still no_healthy, and this
1226		// failed selection must not move the cursor either.
1227		if r := got.Results[13]; r.OK || r.Error != "no_healthy" ||
1228			r.Revision != 3 || r.InstanceID != "" || r.Address != "" {
1229			t.Fatalf("result 13 still no_healthy: %+v", r)
1230		}
1231		// 14-16: at the current revision a sequence of 1 suffices (the reset
1232		// dropped the old sequences 11-13); health reports never bump the
1233		// registration revision, which stays 3.
1234		if r := got.Results[14]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1235			t.Fatalf("result 14: %+v", r)
1236		}
1237		if r := got.Results[15]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1238			t.Fatalf("result 15: %+v", r)
1239		}
1240		if r := got.Results[16]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1241			t.Fatalf("result 16: %+v", r)
1242		}
1243		// 17: the cursor survived the empty list on b, so the rotation continues
1244		// just after b and returns c with its current address and new sequence.
1245		if r := got.Results[17]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 3 {
1246			t.Fatalf("result 17 should resume after b at c: %+v", r)
1247		}
1248		// 18: only now does the rotation wrap back to a.
1249		if r := got.Results[18]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 1 || r.Revision != 3 {
1250			t.Fatalf("result 18 should wrap to a: %+v", r)
1251		}
1252	
1253		// The final list keeps the service at revision 3 with the instances sorted
1254		// by id, all healthy at sequence 1 from the newly accepted observations;
1255		// c's pre-clear unhealthy reason is gone.
1256		if len(got.Services) != 1 {
1257			t.Fatalf("services: %+v", got.Services)
1258		}
1259		svc := got.Services[0]
1260		if svc.Service != "svc" || svc.Revision != 3 {
1261			t.Fatalf("service view: %+v", svc)
1262		}
1263		if len(svc.Instances) != 3 {
1264			t.Fatalf("instances: %+v", svc.Instances)
1265		}
1266		wantInsts := []registerInstance{
1267			{ID: "a", Address: "h1:1", Health: "healthy", Sequence: 1},
1268			{ID: "b", Address: "h2:2", Health: "healthy", Sequence: 1},
1269			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 1},
1270		}
1271		for i, want := range wantInsts {
1272			if svc.Instances[i] != want {
1273				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
1274			}
1275		}
1276	}
1277	
1278	// TestRejectedConflictReplacementKeepsRotationPosition isolates the rotation
1279	// guarantee at the batch level: the conflicting replacement is the very next
1280	// item after the first successful selection, so the following select must
1281	// continue at the next healthy id (i2). A failure path that reset the rotation
1282	// would select i1 again instead. The conflicting list is otherwise valid and
1283	// changes i1's address, which also must not take effect.
1284	func TestRejectedConflictReplacementKeepsRotationPosition(t *testing.T) {
1285		input := `{"requests":[
1286			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1287			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1288			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1289			{"type":"select","service":"svc","expectedRevision":1},
1290			{"type":"register","service":"svc","expectedRevision":7,"instances":[{"id":"i1","address":"hx:8080"},{"id":"i2","address":"h2:8080"}]},
1291			{"type":"select","service":"svc","expectedRevision":1}
1292		]}`
1293		out, code := runRegisterWith(t, input)
1294		if code != 1 {
1295			t.Fatalf("batch contains a failure, exit code: %d, output: %s", code, out)
1296		}
1297		var got registerOutput
1298		if err := json.Unmarshal([]byte(out), &got); err != nil {
1299			t.Fatalf("output is not JSON: %v\n%s", err, out)
1300		}
1301		if len(got.Results) != 6 {
1302			t.Fatalf("results: %+v", got.Results)
1303		}
1304		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 {
1305			t.Fatalf("first select: %+v", r)
1306		}
1307		if r := got.Results[4]; r.OK || r.Error != "conflict" ||
1308			r.Revision != 1 || !hasRevisionPair(r, 7, 1) {
1309			t.Fatalf("conflicting replacement: %+v", r)
1310		}
1311		// The conflict left the cursor just after i1: i2 is next, not i1 again.
1312		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1313			t.Fatalf("select after conflict must continue at i2 with its original state: %+v", r)
1314		}
1315		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
1316			t.Fatalf("services: %+v", got.Services)
1317		}
1318		if insts := got.Services[0].Instances; len(insts) != 2 ||
1319			insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 11 ||
1320			insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "healthy" || insts[1].Sequence != 22 {
1321			t.Fatalf("final list must keep only accepted state: %+v", insts)
1322		}
1323	}
1324	
1325	// TestRejectedInvalidReplacementKeepsRotationPosition is the invalid-content
1326	// counterpart: the malformed replacement follows the first successful
1327	// selection immediately, so the next select must still move to i2 rather than
1328	// repeating i1, and the valid prefix changing i1's address must not apply.
1329	func TestRejectedInvalidReplacementKeepsRotationPosition(t *testing.T) {
1330		input := `{"requests":[
1331			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1332			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1333			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1334			{"type":"select","service":"svc","expectedRevision":1},
1335			{"type":"register","service":"svc","expectedRevision":7,"instances":[{"id":"i1","address":"h9:8080"},{"id":"i2","address":"bad-address"}]},
1336			{"type":"select","service":"svc","expectedRevision":1}
1337		]}`
1338		out, code := runRegisterWith(t, input)
1339		if code != 1 {
1340			t.Fatalf("batch contains a failure, exit code: %d, output: %s", code, out)
1341		}
1342		var got registerOutput
1343		if err := json.Unmarshal([]byte(out), &got); err != nil {
1344			t.Fatalf("output is not JSON: %v\n%s", err, out)
1345		}
1346		if len(got.Results) != 6 {
1347			t.Fatalf("results: %+v", got.Results)
1348		}
1349		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 {
1350			t.Fatalf("first select: %+v", r)
1351		}
1352		// Wrong revision AND invalid content: invalid wins; the reason is the
1353		// address problem, with no expected/actual revision comparison reported.
1354		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
1355			!omitsRevisionPair(r) {
1356			t.Fatalf("invalid replacement: %+v", r)
1357		}
1358		if !strings.Contains(got.Results[4].Reason, `instance address "bad-address" is not a host:port address`) {
1359			t.Fatalf("invalid reason should name the bad address, got %q", got.Results[4].Reason)
1360		}
1361		// i1's valid-prefix new address and any cursor reset must both be absent:
1362		// the rotation continues at i2 with its original address and sequence.
1363		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1364			t.Fatalf("select after invalid replacement must continue at i2 with its original state: %+v", r)
1365		}
1366		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
1367			t.Fatalf("services: %+v", got.Services)
1368		}
1369		if insts := got.Services[0].Instances; len(insts) != 2 ||
1370			insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 11 ||
1371			insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "healthy" || insts[1].Sequence != 22 {
1372			t.Fatalf("final list must keep only accepted state: %+v", insts)
1373		}
1374	}
1375	
1376	// TestSelectSessionKeySticky covers the session flow end to end: the first
1377	// request with a key rotates and binds, later requests with the same trimmed
1378	// key reuse the bound instance without moving the rotation, and plain selects
1379	// interleaved between them keep rotating from the last rotated position.
1380	func TestSelectSessionKeySticky(t *testing.T) {
1381		input := `{"requests":[
1382			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1383			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":1,"healthy":true},
1384			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":2,"healthy":true},
1385			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":3,"healthy":true},
1386			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
1387			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
1388			{"type":"select","service":"svc","expectedRevision":1},
1389			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"  s1  "},
1390			{"type":"select","service":"svc","expectedRevision":1}
1391		]}`
1392		out, code := runRegisterWith(t, input)
1393		if code != 0 {
1394			t.Fatalf("exit code: %d, output: %s", code, out)
1395		}
1396		var got registerOutput
1397		if err := json.Unmarshal([]byte(out), &got); err != nil {
1398			t.Fatalf("output is not JSON: %v\n%s", err, out)
1399		}
1400		if len(got.Results) != 9 {
1401			t.Fatalf("results: %+v", got.Results)
1402		}
1403		// 4: first use of the key rotates to the smallest id and binds s1 -> a.
1404		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 1 {
1405			t.Fatalf("first session select: %+v", r)
1406		}
1407		// 5: reuse returns a again without advancing the rotation.
1408		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Sequence != 1 {
1409			t.Fatalf("session reuse: %+v", r)
1410		}
1411		// 6: a plain select continues just after a, proving the reuse did not
1412		// move the cursor.
1413		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Sequence != 2 {
1414			t.Fatalf("plain select after reuse: %+v", r)
1415		}
1416		// 7: the padded key trims to the same session and still reuses a.
1417		if r := got.Results[7]; !r.OK || r.InstanceID != "a" {
1418			t.Fatalf("padded key should reuse the same session: %+v", r)
1419		}
1420		// 8: the next plain select continues after b.
1421		if r := got.Results[8]; !r.OK || r.InstanceID != "c" || r.Sequence != 3 {
1422			t.Fatalf("plain select should continue after b: %+v", r)
1423		}
1424	}
1425	
1426	// TestSelectSessionKeyFallbackAndRecovery walks a session through the bound
1427	// instance turning unhealthy (fallback rebinds through the rotation), the old
1428	// instance recovering (the binding stays moved), and a no_healthy gap that
1429	// leaves the binding intact for the next reuse.
1430	func TestSelectSessionKeyFallbackAndRecovery(t *testing.T) {
