	// sequence 3 and the unchanged registration revision.
	if r := got.Results[9]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 3 || r.Revision != 1 {
		t.Fatalf("item 10 should reuse the recovered binding a, got %+v", r)
	}
